assert set(P.keys())==set(IDS), "id set mismatch"
assert len(P)==20
os.makedirs(BASE,exist_ok=True)
for cid in IDS:
    d=P[cid]
    assert set(d.keys())=={"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert d["case_id"]==cid and isinstance(d["confidence"],(int,float)) and 0<=d["confidence"]<=1
    assert set(d["trigger"].keys())=={"changed_main","reserve_used","disputed","reason"}
    with open(os.path.join(BASE,cid+".json"),"w",encoding="utf-8") as f:
        json.dump(d,f,ensure_ascii=False,indent=1)
print("written",len(P))
for cid in IDS:
    p=os.path.join(BASE,cid+".json"); assert os.path.exists(p), cid
    json.load(open(p,encoding="utf-8"))
print("verified all 20 exist and parse")
